/**
 * @param {number} n
 * @param {number} k
 * @return {string}
 */
var getPermutation = function(n, k) {
    const nums = Array.from({ length: n }, (_, i) => i + 1);
    let fact = 1;

    for (let i = 1; i <= n - 1; i++) fact *= i;

    k--;
    let ans = '';

    for (let remaining = n; remaining >= 1; remaining--) {
        const index = Math.floor(k / fact);
        ans += nums.splice(index, 1)[0];

        k %= fact;
        if (remaining > 1)
            fact = Math.floor(fact / (remaining - 1));
    }

    return ans;
};

